var n=`0277-bosanski-lonac`;var a=`world-0277`;var i=`BA`;var o=`southern-europe`;var r=4;var s=128;var l={en:`Bosanski Lonac`,ua:`Боснійський лонац`};var g={en:`A traditional Bosnia and Herzegovina dish made with beef chuck, lamb shoulder, yellow onion, carrot. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Боснія і Герцеговина. Основні інгредієнти: яловича лопатка, лопатка ягняти, жовта цибуля, морква. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`beef-chuck`,390,`g`],[`lamb-shoulder`,330,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`yellow-onion`,180,`g`],[`carrot`,180,`g`],[`white-cabbage`,240,`g`],[`potato`,270,`g`],[`green-beans`,170,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 105 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 105 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:105,i:[[`water`,900,`ml`],[`tomato`,220,`g`],[`bay-leaf`,2,`leaf`],[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:a,country:`BA`,region:o,servings:4,minutes:128,title:l,text:g,steps:d};export{i as country,u as default,a as id,s as minutes,o as region,r as servings,n as slug,d as steps,g as text,l as title};